import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    # Boyer-Moore voting
    candidate = None
    count = 0
    for num in arr:
        if count == 0:
            candidate = num
            count = 1
        elif num == candidate:
            count += 1
        else:
            count -= 1

    # Verify
    occ = 0
    for num in arr:
        if num == candidate:
            occ += 1
    if occ > n // 2:
        print(candidate)
    else:
        print(-1)

if __name__ == "__main__":
    main()
